/**
 * View ↔ Runtime 的 stdio JSONL 信封。
 *
 * 沿用 remote-codex-center 网关协议（request/response/notification/serverRequest/log/exit/phase），
 * 传输从 WebSocket 换成 stdio。方向约定：
 *   View → Runtime：request、serverResponse
 *   Runtime → View：response、notification、serverRequest、phase、exit、log
 */
import { z } from 'zod';

/** 信封协议版本；握手（runtime/hello）时双方校验主版本号一致。 */
export const PROTOCOL_VERSION = '0.2.0';

export const JsonRpcError = z.object({
  code: z.number().int(),
  message: z.string(),
  data: z.unknown().optional(),
});
export type JsonRpcError = z.infer<typeof JsonRpcError>;

export const RequestEnvelope = z.object({
  type: z.literal('request'),
  requestId: z.string().min(1),
  /** app-server 方法（如 `turn/start`）或 Runtime 自有方法（如 `workspace/list`） */
  method: z.string().min(1),
  params: z.unknown().optional(),
});
export type RequestEnvelope = z.infer<typeof RequestEnvelope>;

export const ResponseEnvelope = z.object({
  type: z.literal('response'),
  requestId: z.string().min(1),
  result: z.unknown().optional(),
  error: JsonRpcError.optional(),
});
export type ResponseEnvelope = z.infer<typeof ResponseEnvelope>;

export const NotificationEnvelope = z.object({
  type: z.literal('notification'),
  method: z.string().min(1),
  params: z.unknown().optional(),
});
export type NotificationEnvelope = z.infer<typeof NotificationEnvelope>;

/** Codex（经网关）向 View 发起的请求：审批、提问、dynamic tool 调用等。 */
export const ServerRequestEnvelope = z.object({
  type: z.literal('serverRequest'),
  requestId: z.string().min(1),
  method: z.string().min(1),
  params: z.unknown().optional(),
});
export type ServerRequestEnvelope = z.infer<typeof ServerRequestEnvelope>;

export const ServerResponseEnvelope = z.object({
  type: z.literal('serverResponse'),
  requestId: z.string().min(1),
  result: z.unknown().optional(),
  error: JsonRpcError.optional(),
});
export type ServerResponseEnvelope = z.infer<typeof ServerResponseEnvelope>;

export const RuntimePhase = z.enum(['starting', 'running', 'degraded', 'stopped']);
export type RuntimePhase = z.infer<typeof RuntimePhase>;

export const PhaseEnvelope = z.object({
  type: z.literal('phase'),
  phase: RuntimePhase,
  detail: z.string().optional(),
  codex: z
    .object({
      running: z.boolean(),
      version: z.string().optional(),
    })
    .optional(),
});
export type PhaseEnvelope = z.infer<typeof PhaseEnvelope>;

export const ExitEnvelope = z.object({
  type: z.literal('exit'),
  component: z.enum(['codex', 'gateway']),
  exitCode: z.number().int().nullable(),
  signal: z.string().nullable(),
});
export type ExitEnvelope = z.infer<typeof ExitEnvelope>;

export const LogLevel = z.enum(['debug', 'info', 'warn', 'error']);
export type LogLevel = z.infer<typeof LogLevel>;

export const LogEnvelope = z.object({
  type: z.literal('log'),
  level: LogLevel,
  /** 日志来源：gateway / codex / blender / mock … */
  source: z.string(),
  message: z.string(),
  ts: z.number(),
});
export type LogEnvelope = z.infer<typeof LogEnvelope>;

export const Envelope = z.discriminatedUnion('type', [
  RequestEnvelope,
  ResponseEnvelope,
  NotificationEnvelope,
  ServerRequestEnvelope,
  ServerResponseEnvelope,
  PhaseEnvelope,
  ExitEnvelope,
  LogEnvelope,
]);
export type Envelope = z.infer<typeof Envelope>;

/** View → Runtime 允许发送的信封类型 */
export const ViewToRuntimeEnvelope = z.discriminatedUnion('type', [
  RequestEnvelope,
  ServerResponseEnvelope,
]);
export type ViewToRuntimeEnvelope = z.infer<typeof ViewToRuntimeEnvelope>;

/** Runtime → View 允许发送的信封类型 */
export const RuntimeToViewEnvelope = z.discriminatedUnion('type', [
  ResponseEnvelope,
  NotificationEnvelope,
  ServerRequestEnvelope,
  PhaseEnvelope,
  ExitEnvelope,
  LogEnvelope,
]);
export type RuntimeToViewEnvelope = z.infer<typeof RuntimeToViewEnvelope>;

export type ParseResult<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };

export function parseEnvelope(input: unknown): ParseResult<Envelope> {
  const parsed = Envelope.safeParse(input);
  if (parsed.success) return { ok: true, value: parsed.data };
  return { ok: false, error: parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ') };
}

/** 协议版本兼容：主版本号一致即可 */
export function isProtocolCompatible(remote: string, local: string = PROTOCOL_VERSION): boolean {
  const [remoteMajor] = remote.split('.');
  const [localMajor] = local.split('.');
  // 0.x 协议仍在快速演进，minor 改动可能包含破坏性变更。
  if (remoteMajor === '0' || localMajor === '0') return remote === local;
  return remoteMajor !== undefined && remoteMajor === localMajor;
}
